    [MessageHandler(SceneType.GameGate)] [FriendOf(typeof(GatePlayerProxy))]
    public class P2G_WorldPlayerEnteredHandler:MessageHandler<GatePlayerProxy,P2G_WorldPlayerEntered>{protected override async ETTask Run(GatePlayerProxy proxy,P2G_WorldPlayerEntered message){Session session=proxy.Session;if(!Valid(proxy,session,message.PlayerId,message.SessionEpoch))return;G2C_WorldPlayerEntered p=G2C_WorldPlayerEntered.Create();p.WorldRevision=message.WorldRevision;p.Player=OnlineWorldSnapshotHelper.Clone(message.Player);session.Send(p);await ETTask.CompletedTask;}private static bool Valid(GatePlayerProxy p,Session s,long id,long epoch)=>p.IsAuthenticated&&p.PlayerId==id&&p.SessionEpoch==epoch&&s!=null&&!s.IsDisposed;}
