    [MessageHandler(SceneType.GameGate)] [FriendOf(typeof(GatePlayerProxy))]
    public class P2G_WorldCombatChangedHandler:MessageHandler<GatePlayerProxy,P2G_WorldCombatChanged>{protected override async ETTask Run(GatePlayerProxy a,P2G_WorldCombatChanged m){Session s=a.Session;if(!Valid(a,s,m.PlayerId,m.SessionEpoch))return;G2C_WorldCombatChanged p=G2C_WorldCombatChanged.Create();p.WorldId=m.WorldId;p.MapId=m.MapId;p.WorldRevision=m.WorldRevision;p.ServerTime=m.ServerTime;p.CombatSequence=m.CombatSequence;p.ActionKind=m.ActionKind;p.ActorUnitId=m.ActorUnitId;p.WeaponItemId=m.WeaponItemId;foreach(long x in m.TargetUnitIds)p.TargetUnitIds.Add(x);foreach(WorldPlayerInfo x in m.Players)p.Players.Add(OnlineWorldSnapshotHelper.Clone(x));foreach(WorldEnemyInfo x in m.Enemies)p.Enemies.Add(OnlineWorldSnapshotHelper.Clone(x));s.Send(p);await ETTask.CompletedTask;}private static bool Valid(GatePlayerProxy p,Session s,long id,long epoch)=>p.IsAuthenticated&&p.PlayerId==id&&p.SessionEpoch==epoch&&s!=null&&!s.IsDisposed;}
